`, paper\n    39\t`08_classical_and_quantum_low_degree_tests.tex:620-652`. -/\n    40\tnoncomputable def isometryTensor\n    41\t    {ιA ιB κA κB : Type*}\n    42\t    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n    43\t    [Fintype κA] [DecidableEq κA] [Fintype κB] [DecidableEq κB]\n    44\t    (φA : EuclideanSpace ℂ ιA →ₗᵢ[ℂ] EuclideanSpace ℂ κA)\n    45\t    (φB : EuclideanSpace ℂ ιB →ₗᵢ[ℂ] EuclideanSpace ℂ κB)\n    46\t    (ψ : EuclideanSpace ℂ (ιA × ιB)) :\n    47\t    EuclideanSpace ℂ (κA × κB) :=\n    48\t  (EuclideanSpace.equiv (κA × κB) ℂ).symm\n    49\t    (fun p =>\n    50\t      ∑ i : ιA, ∑ j : ιB,\n    51\t        ((EuclideanSpace.equiv κA ℂ)\n    52\t            (φA ((EuclideanSpace.equiv ιA ℂ).symm (Pi.single i 1))) p.1) *\n    53\t          ((EuclideanSpace.equiv κB ℂ)\n    54\t            (φB ((EuclideanSpace.equiv ιB ℂ).symm (Pi.single j 1))) p.2) *\n    55\t          ((EuclideanSpace.equiv (ιA × ιB) ℂ) ψ (i, j)))\n    56\t\n    57\t/-- Coordinate tensor used in the ideal state of blueprint\n    58\t`thm:ms-rigidity`, paper\n    59\t`08_classical_and_quantum_low_degree_tests.tex:620-652`. -/\n    60\tnoncomputable def vecTensor {ι κ : Type*}\n    61\t    [Fintype ι] [DecidableEq ι] [Fintype κ] [DecidableEq κ]\n    62\t    (u : EuclideanSpace ℂ ι) (v : EuclideanSpace ℂ κ) :\n    63\t    EuclideanSpace ℂ (ι × κ) :=\n    64\t  (EuclideanSpace.equiv (ι × κ) ℂ).symm\n    65\t    (fun p => (EuclideanSpace.equiv ι ℂ u) p.1 * (EuclideanSpace.equiv κ ℂ v) p.2)\n    66\t\n    67\t/-- Operator transport used by blueprint\n    68\t`def:strategy-distance`, paper `06_nonlocal_games_and_mipstar.tex:273-285`. -/\n    69\tdef reindexOp {ι ι' : Type*} (e : ι ≃ ι') (M : Op ι') : Op ι :=\n    70\t  (Matrix.reindex e.symm e.symm) M\n    71\t\n    72\t/-- Four-factor tensor shuffle used by blueprint\n    73\t`thm:ms-rigidity`, paper\n    74\t`08_classical_and_quantum_low_degree_tests.tex:620-652`. -/\n    75\tdef prodShuffle {α β γ δ : Type*} :\n    76\t    (α × β) × (γ × δ) ≃ (α × γ) × (β × δ) where\n    77\t  toFun p := ((p.1.1, p.2.1), (p.1.2, p.2.2))\n    78\t  invFun p := ((p.1.1, p.2.1), (p.1.2, p.2.2))\n    79\t  left_inv p := by cases p; rfl\n    80\t  right_inv p := by cases p; rfl\n    81\t\n    82\t/-! ## Norm identities for the coordinate operations -/\n    83\t\n    84\t/-- Reindexing Euclidean coordinates along an equivalence preserves norm.\n    85\tThis is a formalization-only auxiliary identity (no source counterpart). -/\n    86\ttheorem reindexState_norm_eq\n    87\t    {iota kappa : Type*}\n    88\t    [Fintype iota] [DecidableEq iota]\n    89\t    [Fintype kappa] [DecidableEq kappa]\n    90\t    (e : iota ≃ kappa) (psi : EuclideanSpace ℂ iota) :\n    91\t    ‖reindexState e psi‖ = ‖psi‖ := by\n    92\t  rw [← sq_eq_sq₀ (norm_nonneg _) (norm_nonneg _)]\n    93\t  rw [EuclideanSpace.norm_sq_eq, EuclideanSpace.norm_sq_eq]\n    94\t  change (∑ j : kappa, ‖psi (e.symm j)‖ ^ 2) = ∑ i : iota, ‖psi i‖ ^ 2\n    95\t  exact e.symm.sum_comp (fun i => ‖psi i‖ ^ 2)\n    96\t\n    97\t/-- The coordinate tensor of two Euclidean vectors has the product norm.\n    98\tThis is a formalization-only auxiliary identity (no source counterpart). -/\n    99\ttheorem vecTensor_norm_eq\n   100\t    {iota kappa : Type*}\n   101\t    [Fintype iota] [DecidableEq iota]\n   102\t    [Fintype kappa] [DecidableEq kappa]\n   103\t    (u : EuclideanSpace ℂ iota) (v : EuclideanSpace ℂ kappa) :\n   104\t    ‖vecTensor u v‖ = ‖u‖ * ‖v‖ := by\n   105\t  rw [← sq_eq_sq₀ (norm_nonneg _) (mul_nonneg (norm_nonneg _) (norm_nonneg _))]\n   106\t  rw [EuclideanSpace.norm_sq_eq, mul_pow, EuclideanSpace.norm_sq_eq,\n   107\t    EuclideanSpace.norm_sq_eq]\n   108\t  change (∑ p : iota × kappa, ‖u p.1 * v p.2‖ ^ 2) =\n   109\t    (∑ i : iota, ‖u i‖ ^ 2) * ∑ j : kappa, ‖v j‖ ^ 2\n   110\t  simp only [norm_mul, mul_pow]\n   111\t  rw [← Finset.univ_product_univ, Finset.sum_product, Finset.sum_mul]\n   112\t  apply Finset.sum_congr rfl\n   113\t